          packageManifest.peerDependencies = packageManifest.peerDependencies ?? {}
          packageManifest.peerDependencies[packageSpec.alias] = getPeerSpecifier(
            spec,
            packageSpec.resolvedVersion,
            packageSpec.pinnedVersion
